package vn.iotstar.service.impl;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import vn.iotstar.entity.OtpToken;import vn.iotstar.repository.OtpTokenRepository;import vn.iotstar.service.*;import java.security.SecureRandom;import java.time.LocalDateTime;@Service public class OtpServiceImpl implements OtpService{public OtpServiceImpl(OtpTokenRepository repo,PasswordEncoder enc,EmailService mail){this.repo=repo;this.enc=enc;this.mail=mail;}static final int MAX=5;final OtpTokenRepository repo;final PasswordEncoder enc;final EmailService mail;final SecureRandom random=new SecureRandom();private String otp(){return "%06d".formatted(random.nextInt(1000000));}private void send(String e,String type,String sub){repo.deleteByEmailAndType(e,type);String o=otp();repo.save(new OtpToken(null,e,enc.encode(o),type,LocalDateTime.now().plusMinutes(5),0,false,LocalDateTime.now()));mail.sendOtp(e,o,sub);}@Transactional public void sendRegisterOtp(String e){send(e,"REGISTER","Shop - Xác nhận đăng ký tài khoản");}@Transactional public void sendResetPasswordOtp(String e){send(e,"RESET_PASSWORD","Shop - OTP đặt lại mật khẩu");}private boolean verify(String e,String o,String t){OtpToken x=repo.findTopByEmailAndTypeAndUsedFalseOrderByCreatedAtDesc(e,t).orElse(null);if(x==null||x.getExpiresAt().isBefore(LocalDateTime.now())||x.getAttempts()>=MAX)return false;x.setAttempts(x.getAttempts()+1);if(!enc.matches(o,x.getOtpHash())){repo.save(x);return false;}x.setUsed(true);repo.save(x);return true;}@Transactional public boolean verifyRegisterOtp(String e,String o){return verify(e,o,"REGISTER");}@Transactional public boolean verifyResetPasswordOtp(String e,String o){return verify(e,o,"RESET_PASSWORD");}}
